"""Chapter four: authored constraints, physical access puzzles and reproducible maps."""
from chapter4_layout import *
from itertools import permutations,product

def P(fr,en):return pair(fr,en)
def puzzle(l,k,cell,title,mode,rules,method,solution,actions,**kw):
    # Full rules are on the console too: returning to the journal is optional.
    return l.puzzle(k,cell,P(*title),P(*rules),mode,[P('Recoupez les deux notes du secteur et observez le résultat de vos manipulations.','Compare both sector notes and observe the effect of your changes.'),P(*method)],P(*solution),actions,**kw)
def notes(l,k,positions,texts):
    for i,(pos,t) in enumerate(zip(positions,texts)):
        l.clue('n'+str(2*k-1+i),pos,(k+1)*100+1+i,P('Consigne '+str((k+1)*100+1+i),'Instruction '+str((k+1)*100+1+i)),P(*t))
def observations(l,positions,texts):
    for i,(pos,t) in enumerate(zip(positions,texts)):
        l.clue('obs'+str(i),pos,210+i,P(['Registre local A','Registre local B','Registre local C'][i],['Local record A','Local record B','Local record C'][i]),P(*t))
    return [f'c{l.n}_obs{i}' for i in range(3)]
def options(pairs):return [tr(*p) for p in pairs]

l=Level(16,P('Bienvenue, vous habitez ici','Welcome, you live here'),'Une gare en éventail : trois guichets au nord, un hall commun, puis deux labyrinthes de maintenance au sud. Les badges commandent les trois guichets ; le sas 111 mène aux dossiers et le sas 112 aux tubes.',P('« Votre logement, votre emploi et vos opinions sont prêts. Votre arrivée, en revanche, n’a pas été autorisée. Veuillez démontrer votre présence. » — Folamour','“Your home, job and opinions are ready. Your arrival, however, was not authorised. Please demonstrate your presence.” — Folamour'),P('Le dossier retrouvé porte votre numéro de sujet : 16. Une demande de départ y figure déjà, refusée hier, avant votre arrivée. Votre permis provisoire impose une visite du quartier témoin.','The recovered file bears your subject number: 16. It already includes a departure request, refused yesterday, before you arrived. Your temporary permit requires an inspection of the model district.'))
l.layout_en='A fan-shaped station: three northern counters, a shared hall, then two southern maintenance mazes. Badges control the counters; gate 111 leads to records and gate 112 to tubes.'
l.rect(1,33,9,13)
for x in [7,17,27]:l.rect(x-2,x+2,1,5);l.rect(x,x,5,9)
l.maze(1,15,17,33);l.maze(19,33,17,33);l.rect(3,3,13,17);l.rect(15,19,29,29)
obs=observations(l,[(7,3),(17,3),(27,3)],[('A / Résident : le sujet 16 a une clé triangulaire. Aucune clé carrée ne lui appartient.','A / Resident: subject 16 has a triangular key. No square key belongs to them.'),('B / Technicien : le sujet 16 est arrivé par le quai C. Le lecteur garde la trace du badge, pas celle de la personne.','B / Technician: subject 16 arrived at platform C. The reader records the badge, not the person.'),('C / Inspecteur : le dossier valable a un tampon AJOURNÉ. Un dossier ANTICIPÉ décrit un événement qui n’a pas eu lieu.','C / Inspector: the valid file is stamped DEFERRED. An ANTICIPATED file describes an event that has not happened.')])
notes(l,1,[(1,11),(33,11)],[('Le terminal 203 change votre badge. Résident ouvre A ; technicien ouvre B ; inspecteur ouvre C. Un seul badge actif. Les autres portes se ferment.','Terminal 203 changes your badge. Resident opens A; technician opens B; inspector opens C. Only one badge is active. The other doors close.'),('Lire les trois registres 210, 211 et 212, puis revenir au 203 en inspecteur pour certifier la présence. Les changements se font uniquement près du terminal. Les registres lus restent dans le journal.','Read records 210, 211 and 212, then return to 203 as inspector to certify presence. Changes are made only near the terminal. Read records remain in the journal.')])
puzzle(l,1,(17,11),('Le droit d’exister','The right to exist'),'badges',('Installer la mallette. Changer de badge ici, visiter chaque guichet, puis revenir. Lire A en résident, B en technicien et C en inspecteur ; certifier avec le badge inspecteur.','Install the kit. Change badge here, visit each counter, then return. Read A as resident, B as technician and C as inspector; certify with the inspector badge.'),('Chaque badge donne un accès différent. Aucun ne suffit seul. Les trois lectures restent acquises quand vous changez de badge.','Each badge grants a different access. None suffices alone. All three readings remain recorded when you change badges.'),('Depuis 203 : résident → lire 210 → retour ; technicien → lire 211 → retour ; inspecteur → lire 212 → retour. Choisir inspecteur et valider.','From 203: resident → read 210 → return; technician → read 211 → return; inspector → read 212 → return. Select inspector and validate.'),[2],observations=obs,labels=options([('Résident','Resident'),('Technicien','Technician'),('Inspecteur','Inspector')]),world_gates=[dict(cell=[x,7],channel=0,allowed=[i],label='ABC'[i]) for i,x in enumerate([7,17,27])])
notes(l,2,[(1,17),(15,33)],[('Les trois registres du hall décrivent votre dossier : forme de clé, quai et tampon. Les cinq dossiers du pupitre sont complets. Un seul respecte les trois constats ensemble.','The three hall records describe your file: key shape, platform and stamp. The five console files are complete. Only one matches all three observations.'),('A : triangle / B / ajourné. B : carré / C / ajourné. C : triangle / C / anticipé. D : triangle / C / ajourné. E : carré / B / anticipé.','A: triangle / B / deferred. B: square / C / deferred. C: triangle / C / anticipated. D: triangle / C / deferred. E: square / B / anticipated.')])
puzzle(l,2,(7,23),('La personne qui n’est pas arrivée','The person who never arrived'),'records',('Choisir le dossier, puis associer les trois preuves physiques : clé, quai, tampon. Un dossier anticipé ne prouve pas une arrivée.','Choose the file, then attach the three physical facts: key, platform, stamp. An anticipated file does not prove an arrival.'),('Le registre A impose triangle, B impose quai C, C impose ajourné. D est le seul dossier qui combine les trois.','Record A requires triangle, B requires platform C, C requires deferred. D is the only file combining all three.'),('Dossier D ; clé triangle ; quai C ; tampon ajourné. Valider.','File D; triangular key; platform C; deferred stamp. Validate.'),[0,0,0,1,2,2,3],labels=options([('Dossier','File'),('Clé','Key'),('Quai','Platform'),('Tampon','Stamp')]),choices=[['A','B','C','D','E'],options([('Carré','Square'),('Triangle','Triangle')]),['A','B','C'],options([('Anticipé','Anticipated'),('Ajourné','Deferred')])],target=[3,1,2,1])
notes(l,3,[(19,17),(33,33)],[('Deux capsules partent de A puis D. Les aiguillages conservent le même réglage pendant les deux trajets. La capsule de A doit visiter B puis arriver à X. Celle de D doit visiter C puis arriver à Y.','Two capsules start at A then D. Switch settings stay fixed for both trips. The A capsule must visit B then reach X. The D capsule must visit C then reach Y.'),('Chaque aiguillage a deux sorties indiquées sur le schéma. Une boucle est refusée. Tester montre les deux trajets complets ; changer un réglage efface la certification du test.','Each switch has two outputs shown on the diagram. Loops are rejected. Testing displays both complete routes; changing a setting invalidates that test.')])
puzzle(l,3,(27,23),('Les tubes de régularisation','Regularisation tubes'),'tubes',('Régler A, B, C et D pour acheminer A → B → X et D → C → Y, avec les mêmes aiguillages. Le diagramme affiche les deux sorties possibles de chaque nœud. Tester puis valider.','Set A, B, C and D to route A → B → X and D → C → Y with unchanged switches. The diagram shows both possible outputs at every node. Test and validate.'),('Fixer d’abord les arrivées : B doit viser X et C doit viser Y. A rejoint B ; D rejoint C.','Set the destinations first: B points to X and C to Y. A connects to B; D connects to C.'),('A → B ; B → X ; C → Y ; D → C. Tester puis valider.','A → B; B → X; C → Y; D → C. Test and validate.'),[0,2,3,98],edges=[[2,1],[4,0],[1,5],[0,2]],names=['A','B','C','D','X','Y'],starts=[0,3],goals=[4,5],via=[1,2])
l.finish([17,13],[15,11],[19,13],[((1,13),P('Toute personne absente est priée de se présenter immédiatement.','All absent persons must report immediately.')),((15,17),P('Le logement de fonction est équipé d’une fenêtre donnant sur la prochaine fenêtre.','The assigned home includes a window overlooking the next window.')),((19,33),P('Votre recours a été accepté comme preuve de votre insatisfaction.','Your appeal was accepted as evidence of your dissatisfaction.'))],[([3,15],'y'),([17,29],'x')],[33,25])

l=Level(17,P('Le quartier témoin','The model district'),'Une rue verticale dessert trois maisons à horaires décalés, à l’ouest d’un jardin inaccessible. Deux quartiers labyrinthiques occupent le nord-est et le sud-est, reliés par une ruelle étroite.',P('« Ce quartier est notre plus belle réussite. Personne n’y a jamais été surpris. Nous comptons sur vous pour que cela continue. » — Folamour','“This district is our finest achievement. Nobody here has ever been surprised. We count on you to keep it that way.” — Folamour'),P('Ada avait raison : la rue est sèche à midi, malgré l’averse annoncée. Les autres habitants décrivent le bulletin, pas leur fenêtre. MIROIR signale maintenant Ada comme une défaillance du dispositif météorologique.','Ada was right: the street is dry at noon despite the forecast downpour. The other residents describe the bulletin, not their windows. MIRROR now reports Ada as a weather-system failure.'))
l.layout_en='A vertical street serves three houses on different schedules, west of an inaccessible garden. Two maze-like blocks stand northeast and southeast, linked by a narrow lane.'
l.maze(1,5,1,33);l.rect(7,7,1,33);l.rect(5,7,9,9);l.rect(5,7,25,25);l.rect(3,7,17,17)
for y in [5,17,29]:l.rect(11,15,y-2,y+2);l.rect(7,11,y,y)
