obs=observations(l,[(13,5),(13,17),(13,29)],[('MATIN / 08 h : le pluviomètre mécanique indique 0 mm. Le volet de la maison A est fermé. Le pain attend à la boulangerie.','MORNING / 08:00: the mechanical rain gauge reads 0 mm. House A has its shutter closed. Bread waits at the bakery.'),('MIDI / 12 h : le pluviomètre indique encore 0 mm. Ada observe une rue sèche. Le bulletin annonce pourtant une averse. Le volet A est ouvert.','NOON / 12:00: the rain gauge still reads 0 mm. Ada observes a dry street. The bulletin nevertheless announces a downpour. Shutter A is open.'),('SOIR / 18 h : le pluviomètre reste à 0 mm. Boris et Cyril répètent le bulletin de midi. La vitre réelle n’a aucune goutte.','EVENING / 18:00: the gauge remains at 0 mm. Boris and Cyril repeat the noon bulletin. The real window has no drops.')])
notes(l,1,[(1,1),(5,33)],[('Le pupitre 203 change toute la rue entre matin, midi et soir. Aucune horloge réelle. Maison A ouverte le matin, B à midi, C le soir. Les habitants et les volets suivent la phase choisie.','Console 203 switches the street between morning, noon and evening. No real-time clock. House A opens in the morning, B at noon, C in the evening. Residents and shutters follow the chosen phase.'),('Visiter 210, 211 et 212 dans leurs phases respectives. Après les trois observations, revenir à midi pour figer l’état contesté. Les constats restent dans le journal.','Visit 210, 211 and 212 in their respective phases. After all three observations, return to noon to freeze the disputed state. Records stay in the journal.')])
puzzle(l,1,(5,17),('Une journée parfaitement normale','A perfectly normal day'),'routine',('Installer la mallette, choisir une phase, puis visiter la maison accessible. Enregistrer matin, midi et soir. Revenir au pupitre et choisir midi avant de valider.','Install the kit, choose a phase, then visit the accessible house. Record morning, noon and evening. Return to the console and choose noon before validating.'),('Les portes changent avec la phase, les constats s’accumulent. Après les trois visites, midi est la phase de l’alerte.','Doors change with the phase; records accumulate. After all three visits, noon is the phase of the alert.'),('Matin → lire 210 → retour ; midi → lire 211 → retour ; soir → lire 212 → retour. Régler MIDI et valider.','Morning → read 210 → return; noon → read 211 → return; evening → read 212 → return. Set NOON and validate.'),[1],observations=obs,labels=options([('Matin','Morning'),('Midi','Noon'),('Soir','Evening')]),world_gates=[dict(cell=[9,y],channel=0,allowed=[i],label='ABC'[i]) for i,y in enumerate([5,17,29])])
notes(l,2,[(19,1),(33,15)],[('Quatre livraisons aux heures 8, 10, 12 et 14, une par créneau. Ada est livrée avant Boris. Cyril est livré immédiatement avant Daria.','Four deliveries at 8, 10, 12 and 14, one per slot. Ada is delivered before Boris. Cyril is delivered immediately before Daria.'),('Ada n’est pas livrée à 8 h. Boris n’est pas livré à 14 h. Les heures du bulletin sont sans valeur : utilisez les tickets des quatre livraisons.','Ada is not delivered at 8. Boris is not delivered at 14. Bulletin times have no value: use the four delivery tickets.')])
