puzzle(l,2,(25,7),('Le facteur qui livre hier','The postman delivering yesterday'),'timetable',('Une livraison à 8, 10, 12 et 14 h. Ada avant Boris ; Cyril immédiatement avant Daria ; Ada pas à 8 h ; Daria pas à 14 h. Une seule personne par heure.','One delivery at 8, 10, 12 and 14. Ada before Boris; Cyril immediately before Daria; Ada not at 8; Daria not at 14. One person per slot.'),('Le duo Cyril-Daria ne peut occuper 12-14. S’il occupait 10-12, Ada serait forcée à 8. Donc Cyril 8, Daria 10, Ada 12, Boris 14.','Cyril-Daria cannot occupy 12-14. At 10-12, Ada would be forced to 8. Therefore Cyril 8, Daria 10, Ada 12, Boris 14.'),('Ada 12 ; Boris 14 ; Cyril 8 ; Daria 10. Valider.','Ada 12; Boris 14; Cyril 8; Daria 10. Validate.'),[0,0,1,1,1,3],labels=['Ada','Boris','Cyril','Daria'],choices=[['08:00','10:00','12:00','14:00']]*4,target=[2,3,0,1])
notes(l,3,[(19,19),(33,33)],[('Ada : « La rue est sèche à midi. » Boris : « Averse confirmée par la radio. » Cyril : « Averse confirmée par Boris. » Daria : « Le volet A reste fermé toute la journée. »','Ada: “The street is dry at noon.” Boris: “Downpour confirmed by radio.” Cyril: “Downpour confirmed by Boris.” Daria: “Shutter A stays closed all day.”'),('Une observation fiable doit correspondre aux trois relevés et provenir d’un constat direct. La radio diffuse MIROIR. Choisir le témoin et les deux instruments indépendants, pas les copies.','A reliable observation must match all three records and come from direct observation. The radio broadcasts MIRROR. Choose the witness and the two independent instruments, not copies.')])
puzzle(l,3,(27,25),('L’anomalie est dans le bulletin','The anomaly is in the bulletin'),'anomaly',('Choisir le témoin fiable. Joindre exactement deux preuves indépendantes parmi pluviomètre, radio, vitre réelle et rapport de Boris.','Choose the reliable witness. Attach exactly two independent proofs from rain gauge, radio, real window and Boris’s report.'),('Ada voit directement la rue. Le pluviomètre et la vitre vérifient son constat sans dépendre de MIROIR.','Ada sees the street directly. The rain gauge and window verify her observation independently of MIRROR.'),('Ada ; conserver pluviomètre et vitre réelle ; écarter radio et rapport de Boris. Valider.','Ada; keep rain gauge and real window; exclude radio and Boris’s report. Validate.'),[1,3],labels=options([('Témoin','Witness'),('Pluviomètre','Rain gauge'),('Radio','Radio'),('Vitre réelle','Real window'),('Rapport de Boris','Boris’s report')]),choices=[['Ada','Boris','Cyril','Daria']]+[options([('Écarter','Exclude'),('Conserver','Keep')])]*4,target=[0,1,0,1,0])
l.finish([7,33],[7,31],[7,27],[((1,33),P('Le bonheur est obligatoire. Toute amélioration sera considérée comme une critique.','Happiness is compulsory. Any improvement will be treated as criticism.')),((33,1),P('Le facteur a livré demain. Sa ponctualité fait l’objet d’une enquête.','The postman delivered tomorrow. His punctuality is under investigation.')),((19,33),P('Le jardin est interdit aux plantes non prévues au plan.','Plants absent from the plan are forbidden in the garden.'))],[([17,1],'x'),([31,17],'y')],[33,23])

l=Level(18,P('Le ministère des regards','The ministry of gazes'),'Deux anneaux de surveillance entourent une tour centrale. Depuis l’anneau extérieur, trois niches à l’est se ferment selon les caméras. Un pont ouest mène aux montages ; une entrée nord mène aux sources.',P('« Pour obtenir votre certificat de discrétion, veuillez réparer les appareils qui vous regardent. Ils sont momentanément occupés à s’observer entre eux. » — Folamour','“To obtain your discretion certificate, repair the devices watching you. They are currently busy observing one another.” — Folamour'),P('Les trois alertes prétendument indépendantes remontent toutes au même bulletin. Le film original montre un chariot de nettoyage. MIROIR en avait déduit une invasion, puis demandé une confirmation à sa propre copie.','All three supposedly independent alerts trace back to one bulletin. The original film shows a cleaning cart. MIRROR inferred an invasion, then asked its own copy to confirm it.'))
l.layout_en='Two surveillance rings surround a central tower. Three eastern niches off the outer ring close according to camera settings. A western bridge leads to editing; a northern entry leads to sources.'
l.rect(1,33,1,33);l.rect(6,28,6,28,0);l.rect(9,25,9,25);l.rect(13,21,13,21,0);l.rect(15,19,15,19);l.rect(5,9,17,17);l.rect(17,17,9,15)
