obs=observations(l,[(27,7),(27,17),(27,27)],[('A / La caméra archive le chariot à 09:10. Il transporte un balai. Aucun autre véhicule n’est visible.','A / The camera records the cart at 09:10. It carries a broom. No other vehicle is visible.'),('B / Le poste B déclenche un verrou lorsqu’il regarde vers l’ouest. Son image montre une copie de l’écran A, pas une deuxième caméra.','B / Station B locks when it looks west. Its image shows a copy of screen A, not a second camera.'),('C / La transmission mécanique confirme le passage du même chariot. La signature de MIROIR est ajoutée après la copie.','C / The mechanical transmission confirms the same cart’s passage. MIRROR’s signature is added after copying.')])
notes(l,1,[(1,1),(33,33)],[('A ouvre la niche A en regardant EST. B ferme la niche B en regardant OUEST : toute autre direction la libère. C ouvre la niche C en regardant NORD.','A opens niche A when looking EAST. B closes niche B when looking WEST: any other direction releases it. C opens niche C when looking NORTH.'),('Lire les trois registres 210-212 puis laisser les trois accès ouverts. Le panneau montre les orientations et l’état réel des portes. Les réglages se font au poste 203 seulement.','Read all three records 210-212, then leave all three accesses open. The panel shows orientations and actual gate states. Settings change only at station 203.')])
puzzle(l,1,(31,17),('Voir pour ouvrir, détourner pour passer','Look to open, look away to pass'),'gaze',('Installer la mallette. A vers EST ouvre A ; B vers OUEST ferme B ; C vers NORD ouvre C. Régler les caméras, lire les trois niches physiques, puis valider avec tous les accès ouverts.','Install the kit. A EAST opens A; B WEST closes B; C NORTH opens C. Set the cameras, read the three physical niches, then validate with all accesses open.'),('La caméra B inverse la règle : il faut détourner son regard. Les directions nord, est et sud sont toutes valables pour B.','Camera B reverses the rule: look away. North, east and south all work for B.'),('A EST ; B SUD (ou NORD/EST) ; C NORD. Visiter 210, 211 et 212. Retour au 203, tester puis valider.','A EAST; B SOUTH (or NORTH/EAST); C NORTH. Visit 210, 211 and 212. Return to 203, test and validate.'),[0,1,1,98],observations=obs,world_gates=[dict(cell=[28,y],channel=i,allowed=allowed,label='ABC'[i]) for i,(y,allowed) in enumerate(zip([7,17,27],[[1],[0,1,2],[0]]))])
notes(l,2,[(9,9),(25,25)],[('Chaque fragment montre le début et la fin d’une action. Relier la fin d’un fragment au début du suivant. Commencer PORTE FERMÉE, finir RUE VIDE. Utiliser chaque fragment une seule fois.','Each fragment shows an action’s start and end. Join each fragment’s end to the next start. Begin CLOSED DOOR, end EMPTY STREET. Use each fragment exactly once.'),('A : chariot → balai. B : porte fermée → porte ouverte. C : balai → chariot. D : porte ouverte → chariot. E : chariot → rue vide. Sortir trop tôt par E abandonne le nettoyage.','A: cart → broom. B: closed door → open door. C: broom → cart. D: open door → cart. E: cart → empty street. Leaving early through E skips the cleaning.')])
puzzle(l,2,(11,17),('Le film coupé trop court','The film cut too short'),'splice',('Assembler les cinq fragments en raccordant leurs états. Départ porte fermée, fin rue vide. Chaque fragment une fois. Tester montre les raccords, y compris un éventuel retour au chariot.','Assemble all five fragments by matching states. Start closed door, finish empty street. Each fragment once. Testing shows the joins, including a possible return to the cart.'),('B ouvre la porte, D fait entrer le chariot. Le détour A-C explique le nettoyage. E termine le film.','B opens the door, D brings in the cart. The A-C detour explains the cleaning. E ends the film.'),('B → D → A → C → E. Tester puis valider.','B → D → A → C → E. Test and validate.'),[1,3,0,2,4,98],cards=options([('A · Chariot → balai','A · Cart → broom'),('B · Porte fermée → ouverte','B · Closed → open door'),('C · Balai → chariot','C · Broom → cart'),('D · Porte ouverte → chariot','D · Open door → cart'),('E · Chariot → rue vide','E · Cart → empty street')]),joins=[[2,3],[0,1],[3,2],[1,2],[2,4]],max_commands=5)
notes(l,3,[(15,15),(19,19)],[('R1 cite R2. R2 cite R3. R3 cite MIROIR. R4 vient du capteur mécanique. R5 copie R4. Une copie conserve l’origine et ne crée jamais une mesure indépendante.','R1 cites R2. R2 cites R3. R3 cites MIRROR. R4 comes from the mechanical sensor. R5 copies R4. A copy retains its origin and never creates an independent measurement.'),('Attribuer à R1-R5 leur origine ultime. Puis annoncer combien de familles de mesures physiques indépendantes figurent dans ces cinq rapports. Une famille copiée compte une seule fois.','Assign the ultimate origin of R1-R5. Then report how many independent physical measurement families appear in these reports. A copied family counts only once.')])
puzzle(l,3,(15,17),('Une rumeur en cinq exemplaires','A rumour in five copies'),'origins',('Remonter R1 → R2 → R3 → MIROIR et R5 → R4 → capteur. Classer chaque origine ultime et compter les familles physiques indépendantes.','Trace R1 → R2 → R3 → MIRROR and R5 → R4 → sensor. Classify ultimate origins and count independent physical families.'),('R1, R2 et R3 sont issus de MIROIR. R4 et R5 sont une seule famille mécanique. Le nombre de signatures ne compte pas.','R1, R2 and R3 come from MIRROR. R4 and R5 form one mechanical family. Signature count is irrelevant.'),('R1-R3 : MIROIR ; R4-R5 : capteur ; familles physiques : 1. Valider.','R1-R3: MIRROR; R4-R5: sensor; physical families: 1. Validate.'),[3,4,5],labels=['R1','R2','R3','R4','R5',tr('Familles physiques','Physical families')],choices=[['MIROIR',tr('Capteur','Sensor')]]*5+[['0','1','2','3','4','5']],target=[0,0,0,1,1,1])
l.finish([3,31],[1,31],[5,31],[((1,33),P('Pour votre intimité, cette caméra est équipée d’un rideau dessiné.','For your privacy, this camera includes a painted curtain.')),((25,9),P('Le service des angles morts refuse de communiquer son adresse.','The blind-spot department refuses to disclose its address.')),((19,15),P('Une caméra surveille le voyant indiquant qu’elle ne surveille personne.','A camera watches the indicator stating it watches nobody.'))],[([7,17],'x'),([17,13],'y')],[17,19])

l=Level(19,P('La fabrique du lendemain','The tomorrow factory'),'Trois chaînes en tresses traversent le complexe : énergie à l’ouest, convoyeurs au centre, assemblage à l’est. Les passerelles changent de hauteur sur le plan ; les ateliers latéraux forment des boucles de retour.',P('« Nous produisons aujourd’hui les solutions aux problèmes que nous annoncerons demain. Votre ascenseur est une commande mineure. Essayez de ne pas déranger les grandes. » — Folamour','“Today we produce solutions to problems we will announce tomorrow. Your lift is a minor order. Try not to disturb the major ones.” — Folamour'),P('L’ascenseur est réparé. Derrière sa pièce minuscule, les chaînes poursuivent des coques effilées, des systèmes de guidage et des capsules de tranquillité. La commande porte la mention HORIZON. Il manque seulement l’accord du directoire.','The lift is repaired. Behind its tiny part, the lines keep producing tapered shells, guidance systems and tranquillity capsules. The order is marked HORIZON. Only the directorate’s approval is missing.'))
