notes(l,1,[(13,1),(21,9)],[('Cinq bureaux : habitat, météo, sécurité, industrie, transport. Affecter à chacun une preuve originale. Le dossier d’arrivée ne va ni à la météo ni à l’industrie. Le pluviomètre va au service qui annonce le temps.','Five offices: housing, weather, security, industry, transport. Assign one original proof to each. The arrival file belongs to neither weather nor industry. The rain gauge belongs to the weather office.'),('Le film du chariot va à la sécurité. Le bon des coques va à l’industrie. Le test de l’ascenseur va au transport. Chaque preuve et chaque bureau sont utilisés une fois.','The cart film belongs to security. The shell order belongs to industry. The lift test belongs to transport. Use every proof and office once.')])
puzzle(l,1,(17,17),('Cinq faits contre cinq certitudes','Five facts against five certainties'),'exhibits',('Affecter une preuve à chaque bureau, sans doublon. Les copies ont été retirées ; les cinq originaux sont disponibles, même lors d’un accès direct à ce niveau.','Assign one proof to each office without duplicates. Copies have been removed; all five originals are available even when starting this level directly.'),('Sécurité reçoit film, industrie reçoit commande, transport reçoit ascenseur, météo reçoit pluviomètre. Le dossier d’arrivée reste pour habitat.','Security gets film, industry gets order, transport gets lift, weather gets rain gauge. The arrival file remains for housing.'),('Habitat : dossier ; météo : pluviomètre ; sécurité : film ; industrie : commande ; transport : ascenseur. Valider.','Housing: file; weather: rain gauge; security: film; industry: order; transport: lift. Validate.'),[0,0,1,1,1,1,3,4,4,4],labels=options([('Habitat','Housing'),('Météo','Weather'),('Sécurité','Security'),('Industrie','Industry'),('Transport','Transport')]),choices=[options([('Film','Film'),('Commande','Order'),('Dossier','File'),('Ascenseur','Lift'),('Pluviomètre','Rain gauge')])]*5,target=[2,4,0,1,3])
notes(l,2,[(1,1),(9,33)],[('A peut croire B ou le capteur X. B peut croire C ou A. C peut croire A ou le capteur Y. D peut croire E ou B. E peut croire D ou C. X et Y sont les seuls constats physiques.','A may trust B or sensor X. B may trust C or A. C may trust A or sensor Y. D may trust E or B. E may trust D or C. X and Y are the only physical observations.'),('A et B doivent finir sur X ; C, D et E doivent finir sur Y. Aucune boucle n’est recevable. Une chaîne de copies aboutissant au bon capteur est recevable, mais ne multiplie pas les preuves.','A and B must terminate at X; C, D and E at Y. No loop is admissible. A copy chain ending at the right sensor is admissible but does not multiply evidence.')])
puzzle(l,2,(5,17),('Le réseau de confiance','The trust network'),'trust',('Choisir une source pour chaque bureau. A et B doivent remonter à X ; C, D et E à Y. Tester trace toutes les chaînes et signale les boucles.','Choose each office’s source. A and B must trace to X; C, D and E to Y. Testing traces every chain and reports loops.'),('A doit joindre X, B doit joindre A, C doit joindre Y. D ne peut passer par B (origine X) : il rejoint E, qui rejoint C.','A must join X, B must join A, C must join Y. D cannot use B (origin X): it joins E, which joins C.'),('A → X ; B → A ; C → Y ; D → E ; E → C. Tester puis valider.','A → X; B → A; C → Y; D → E; E → C. Test and validate.'),[0,1,2,4,98],edges=[[1,5],[2,0],[0,6],[4,1],[3,2]],names=['A','B','C','D','E','X','Y'],goals=[5,5,6,6,6])
notes(l,3,[(25,1),(33,33)],[('Quatre copies portent leurs dossiers au cinquième Folamour par une passerelle. Durées : A=1, B=2, C=5, D=8 unités. Au plus deux copies traversent ensemble. Le sceau unique doit accompagner chaque traversée et chaque retour.','Four copies carry files to the fifth Folamour across a walkway. Durations: A=1, B=2, C=5, D=8 units. At most two copies cross together. The single seal accompanies every outward and return crossing.'),('Une traversée coûte la durée du plus lent. Tout le monde part côté bureaux. Amener les quatre copies et le sceau au conseil en 15 unités maximum. Le temps avance uniquement quand vous appuyez sur Traverser. Annuler restitue le temps.','A crossing costs the slower traveller’s duration. Everyone starts on the office side. Bring all four copies and the seal to the council within 15 units. Time advances only when pressing Cross. Undo restores time.')])
puzzle(l,3,(29,17),('Le sceau à usage collectif','The shared seal'),'seal',('Sélectionner une ou deux copies du côté du sceau, puis Traverser. Coût = durée du plus lent : A1, B2, C5, D8. Tous au conseil en 15 unités maximum. Aucune limite en temps réel. Annulation et remise à zéro disponibles.','Select one or two copies on the seal’s side, then Cross. Cost = slower duration: A1, B2, C5, D8. Everyone must reach the council in at most 15 units. No real-time limit. Undo and reset are available.'),('Faire voyager C et D ensemble économise leurs longs trajets. A et B servent de passeurs du sceau. Le plus rapide ne doit pas faire tous les retours.','Send C and D together to combine their long crossings. A and B shuttle the seal. The fastest should not make every return.'),('A+B aller (2), A retour (1), C+D aller (8), B retour (2), A+B aller (2). Total 15. Valider.','A+B across (2), A returns (1), C+D across (8), B returns (2), A+B across (2). Total 15. Validate.'),[0,1,98,0,98,2,3,98,1,98,0,1,98],times=[1,2,5,8],budget=15)
l.finish([17,21],[15,21],[19,21],[((21,1),P('Folamour original : « Les quatre autres sont des copies. » Exemplaire 5 sur 5.','Original Folamour: “The other four are copies.” Copy 5 of 5.')),((1,33),P('Le conseil a voté l’interdiction des votes divisés. Résultat : cinq versions différentes du procès-verbal.','The council banned divided votes. Result: five different minutes.')),((33,1),P('Programme HORIZON. Destination : suffisamment loin. Retour : non prévu au formulaire.','HORIZON programme. Destination: far enough. Return: absent from the form.'))],[([11,17],'x'),([23,17],'x')],[17,3])

# Persist metadata and bilingual additions. Dynamic visits get an executable route:
# walk to console, change setting, visit niche, return. No teleports in tests.
for n in range(16,21):
 E=json.loads((D/f'events{n}.json').read_text());by={e['id']:e for e in E};m=json.loads((D/f'maze{n}.json').read_text());F={(x,y) for y,row in enumerate(m['grid']) for x,v in enumerate(row) if v}
 p1=by[f'c{n}_p1'];route=json.loads((T/f'route_level{n}.json').read_text())
 if p1.get('world_gates'):
  # Recompute a physically legal route, inserting the three field visits just before p1.
  regular=[s['id'] for s in route if '_obs' not in s['id']];current=tuple(m['start']);done=set();new=[];settings=[0,0,0];collected=False
  def walk_to(id,actions=None):
   global current
   e=by[id];closed={tuple(e['cell']) for e in E if e['kind'] in ['door','exit'] and e['id'] not in done}
   if p1['id'] not in done:
    closed|={tuple(b['cell']) for b in p1['world_gates'] if settings[b['channel']] not in b['allowed']}
   targets=set(neighbours(tuple(e['cell']))) if e['kind']=='exit' else {tuple(e['cell'])}
   p=path(current,targets,F-closed);assert p,(n,id,current,settings)
   s=dict(id=id,route=p)
   if actions is not None:s['configure']=actions
   new.append(s);current=p[-1]
   if actions is None:done.add(id);done.update(e.get('opens',[]))
  for id in regular:
   if id==p1['id']:
    for i in range(3):
     acts=[i] if n in [16,17] else ([0] if i==0 else [])
     walk_to(id,acts)
     if n in [16,17]:settings[0]=i
     elif i==0:settings[0]=1
     walk_to(f'c{n}_obs{i}')
    walk_to(id,[])
   walk_to(id)
  route=new;save(T/f'route_level{n}.json',route)
 # Ensure all new complete titles/journal concatenations can localize.
 for e in E:
  en[e['title']+'\n'+e['text']]=en.get(e['title'],e['title'])+'\n'+en.get(e['text'],e['text'])
# static console strings
for fr,eng in [
 ('VERSION 0.18 · LE COMPLEXE DE LA CERTITUDE','VERSION 0.18 · THE CERTAINTY COMPLEX'),('Chapitre 4 — Le complexe de la certitude','Chapter 4 — The certainty complex'),('Reprendre le chapitre 4','Resume chapter 4'),('Entrer dans le complexe de la certitude','Enter the certainty complex'),('CHAPITRE 4 / LE COMPLEXE DE LA CERTITUDE','CHAPTER 4 / THE CERTAINTY COMPLEX'),('CHAPITRE 4 / MISSION TERMINÉE','CHAPTER 4 / ASSIGNMENT COMPLETE'),('CHAPITRE 4 TERMINÉ','CHAPTER 4 COMPLETE'),('Le chapitre 5 n’est pas encore jouable. Votre bilan est sauvegardé.','Chapter 5 is not playable yet. Your results are saved.'),('C4 / MISSION %d','C4 / ASSIGNMENT %d'),('Modifier ces accès exige de revenir au pupitre.','Return to the console to change these accesses.'),('Registres consultés : %d / 3','Records read: %d / 3'),('Réglage','Setting'),('OUVERT','OPEN'),('FERMÉ','CLOSED'),('Tester les trajets','Test routes'),('Boucle détectée','Loop detected'),('Opération hors ordre','Operation out of order'),('Trajet interrompu','Route interrupted'),('Dépendance manquante','Missing dependency'),('Raccord impossible','Join mismatch'),('Temps utilisé : %d / %d','Time used: %d / %d'),('Côté bureaux','Office side'),('Côté conseil','Council side'),('Sceau : %s','Seal: %s'),('Traverser','Cross'),('Annuler la traversée','Undo crossing'),('Sélectionner une ou deux copies du côté du sceau.','Select one or two copies on the seal’s side.'),('Budget dépassé : annuler une traversée ou réinitialiser.','Budget exceeded: undo a crossing or reset.'),('Presse : %d / 5','Press: %d / 5'),('Refroidissement : %d / 4','Cooling: %d / 4'),('Guidage : %d / 3','Guidance: %d / 3'),('Essai non conforme : vérifier les règles, les lectures physiques et le dernier test.','Trial not compliant: check rules, physical readings and latest test.'),('Réseau : sorties 0 / 1','Network: outputs 0 / 1'),('BUREAUX','OFFICES'),('CONSEIL','COUNCIL'),('Porte %s : %s','Gate %s: %s')]:tr(fr,eng)
